@triton.jit(do_not_specialize=["nnode", "nz", "ny", "nx", "cy", "cx"])
def gather_kernel(base_ptr, loc_ptr, out_ptr, nnode, nz, ny, nx, cy, cx, BLOCK: tl.constexpr):
    """out[n,r] = base[n,r] + sum_{a=0..7} loc[cell(n,a), a, r] in fixed vertex order (no atomics)."""
    i = (tl.program_id(0)*BLOCK+tl.arange(0, BLOCK)).to(tl.int64)
    m = i < nnode*3
    n = i//3
    r = i % 3
    x = n % nx
    y = (n//nx) % ny
    z = n//(nx*ny)
    acc = tl.load(base_ptr+i, mask=m, other=0.)
    x0 = x-0; y0 = y-0; z0 = z-0
    ok0 = m & (x0 >= 0) & (x0 < cx) & (y0 >= 0) & (y0 < cy) & (z0 >= 0) & (z0 < nz-1)
    cell0 = (z0*cy+y0)*cx+x0
    acc += tl.load(loc_ptr+cell0*24+0+r, mask=ok0, other=0.)
    x1 = x-1; y1 = y-0; z1 = z-0
    ok1 = m & (x1 >= 0) & (x1 < cx) & (y1 >= 0) & (y1 < cy) & (z1 >= 0) & (z1 < nz-1)
    cell1 = (z1*cy+y1)*cx+x1
    acc += tl.load(loc_ptr+cell1*24+3+r, mask=ok1, other=0.)
    x2 = x-0; y2 = y-1; z2 = z-0
    ok2 = m & (x2 >= 0) & (x2 < cx) & (y2 >= 0) & (y2 < cy) & (z2 >= 0) & (z2 < nz-1)
    cell2 = (z2*cy+y2)*cx+x2
    acc += tl.load(loc_ptr+cell2*24+6+r, mask=ok2, other=0.)
    x3 = x-1; y3 = y-1; z3 = z-0
    ok3 = m & (x3 >= 0) & (x3 < cx) & (y3 >= 0) & (y3 < cy) & (z3 >= 0) & (z3 < nz-1)
    cell3 = (z3*cy+y3)*cx+x3
    acc += tl.load(loc_ptr+cell3*24+9+r, mask=ok3, other=0.)
    x4 = x-0; y4 = y-0; z4 = z-1
    ok4 = m & (x4 >= 0) & (x4 < cx) & (y4 >= 0) & (y4 < cy) & (z4 >= 0) & (z4 < nz-1)
    cell4 = (z4*cy+y4)*cx+x4
    acc += tl.load(loc_ptr+cell4*24+12+r, mask=ok4, other=0.)
    x5 = x-1; y5 = y-0; z5 = z-1
    ok5 = m & (x5 >= 0) & (x5 < cx) & (y5 >= 0) & (y5 < cy) & (z5 >= 0) & (z5 < nz-1)
    cell5 = (z5*cy+y5)*cx+x5
    acc += tl.load(loc_ptr+cell5*24+15+r, mask=ok5, other=0.)
    x6 = x-0; y6 = y-1; z6 = z-1
    ok6 = m & (x6 >= 0) & (x6 < cx) & (y6 >= 0) & (y6 < cy) & (z6 >= 0) & (z6 < nz-1)
    cell6 = (z6*cy+y6)*cx+x6
    acc += tl.load(loc_ptr+cell6*24+18+r, mask=ok6, other=0.)
    x7 = x-1; y7 = y-1; z7 = z-1
    ok7 = m & (x7 >= 0) & (x7 < cx) & (y7 >= 0) & (y7 < cy) & (z7 >= 0) & (z7 < nz-1)
    cell7 = (z7*cy+y7)*cx+x7
    acc += tl.load(loc_ptr+cell7*24+21+r, mask=ok7, other=0.)
    tl.store(out_ptr+i, acc, mask=m)


@triton.jit
def _barrier_second(J, w, delta, act, scale):
    r = tl.maximum(act-J, 0.)/scale
    t = (tl.minimum(J, act)-delta)/scale
    logt = tl.where(r < .5, libdevice.log1p(-r), libdevice.log(t))
    q = r/t
    return w*(-2.*logt+4.*q+q*q)/(scale*scale)


